#define PLL_DIV_CFG_FBDIV_MASK		GENMASK(11, 0)
#define PLL_DIV_CFG_POSTDIV1_MASK	GENMASK(18, 16)
#define PLL_DIV_CFG_POSTDIV2_MASK	GENMASK(22, 20)
#define PLL_DIV_CFG_REFDIV_MASK		GENMASK(29, 24)

#define PLL_CTRL_DIV_SEL_REF_CLK		0
#define PLL_CTRL_DIV_SEL_PLL_CLK		1
#define PLL_CTRL_DIV_SEL_DIVIDED_REF_CLK	2
#define PLL_CTRL_DIV_SEL_DIVIDED_PLL_CLK	3

#define REF_CLOCK_MHZ		50
#define PLL_FBDIV_MASK		GENMASK(11, 0)
#define PLL_POSTDIV1_MASK	GENMASK(18, 16)
#define PLL_POSTDIV2_MASK	GENMASK(22, 20)
#define PLL_REFDIV_MASK		GENMASK(29, 24)

#define GAUID2_INIT_PLL_COEFFICIENT(pll, refdiv, fbdiv, pdiv1, pdiv2) \
do { \
	pll->div_cfg = FIELD_PREP(PLL_DIV_CFG_REFDIV_MASK, refdiv); \
	pll->div_cfg |= FIELD_PREP(PLL_DIV_CFG_FBDIV_MASK, fbdiv); \
	pll->div_cfg |= FIELD_PREP(PLL_DIV_CFG_POSTDIV1_MASK, pdiv1); \
	pll->div_cfg |= FIELD_PREP(PLL_DIV_CFG_POSTDIV2_MASK, pdiv2); \
} while (0)

#define SET_SELECTOR_USING_DIVIDER(divider) \
({ \
	divider ? PLL_CTRL_DIV_SEL_DIVIDED_PLL_CLK : PLL_CTRL_DIV_SEL_PLL_CLK; \
})

#define GAUDI2_INIT_PLL_DIV_SELECTOR(pll, d0, d1, d2, d3) \
do { \
	pll->div_sel[0] = SET_SELECTOR_USING_DIVIDER(d0); \
	pll->div_sel[1] = SET_SELECTOR_USING_DIVIDER(d1); \
	pll->div_sel[2] = SET_SELECTOR_USING_DIVIDER(d2); \
	pll->div_sel[3] = SET_SELECTOR_USING_DIVIDER(d3); \
} while (0)

#define GAUDI2_INIT_PLL_DIVIDER_VAL(pll, d0, d1, d2, d3) \
do { \
	pll->div_fact[0] = d0; \
	pll->div_fact[1] = d1; \
	pll->div_fact[2] = d2; \
	pll->div_fact[3] = d3; \
	GAUDI2_INIT_PLL_DIV_SELECTOR(pll, d0, d1, d2, d3); \
} while (0)

/*
 * CPU works with 40 bits addressing while the chip with 64 bits.
 * to overcome the gap address bits [38:39] are used to determine what
 * extension the FW should take (SRAM, DRAM...)
 * 00: CFG
 * 01: SRAM
 * 10: HBM
 * 11: PCI
 */
#define GAUDI2_SRAM_TO_CPU_ADDR(addr)			\
do {						\
	(addr) &= ~GENMASK_ULL(63, 38);		\
	(addr) |= BIT_ULL(38);			\
} while (0)

/**
 * struct cluster_binning_cfg - cluster binning configuration
 * @xbar_edge_iso: value of XBAR EDGE isolation reg
 * @hif_hmmu_iso: value of HMMU isolation reg
 * @hif_hmmu_enabled: bit mask of enabled HMMU/HIF (1- enabled, 0- disabled)
 * @cluster_edma: EDMA index to be binned for the cluster
 */
struct cluster_binning_cfg {
	u32 xbar_edge_iso;
	u32 hif_hmmu_iso;
	u32 hif_hmmu_enabled;
	u8 cluster_edma;
};

/*
 * Note that each bit in the HIF_HMMU_ISO has specific mapping.
 * the enabled mask correspond to the HMMU/HIF SoC-online ordering (bit 0 is
 * DCORE_0_HIF0, bit 1 is DCORE_0_HIF1 and so on).
 */
static struct cluster_binning_cfg cluster_binning_cfg_table[GAUDI2_HBM_NUM] = {
	[HBM_ID0] = {
		.xbar_edge_iso = 0x1,
		.hif_hmmu_iso = 0x3,
		.hif_hmmu_enabled = 0xFFFC,
		.cluster_edma = 0,
	},
	[HBM_ID1] = {
		.xbar_edge_iso = 0x2,
		.hif_hmmu_iso = 0x30,
		.hif_hmmu_enabled = 0xFFCF,
		.cluster_edma = 2,
	},
	[HBM_ID2] = {
		.xbar_edge_iso = 0x0,
		.hif_hmmu_iso = 0x108,
		.hif_hmmu_enabled = 0xF7F7,
		.cluster_edma = 1,
	},
	[HBM_ID3] = {
		.xbar_edge_iso = 0x0,
		.hif_hmmu_iso = 0x1080,
		.hif_hmmu_enabled = 0x7F7F,
		.cluster_edma = 3,
	},
	[HBM_ID4] = {
		.xbar_edge_iso = 0x4,
		.hif_hmmu_iso = 0xC00,
		.hif_hmmu_enabled = 0xFCFF,
		.cluster_edma = 5,
	},
	[HBM_ID5] = {
		.xbar_edge_iso = 0x8,
		.hif_hmmu_iso = 0xC000,
		.hif_hmmu_enabled = 0xCFFF,
		.cluster_edma = 7,
	},
};


enum xbar_id {
	XBAR_ID_MID_0,
	XBAR_ID_EDGE_0,
	XBAR_ID_MID_1,
	XBAR_ID_EDGE_1,
	XBAR_ID_MID_2,
	XBAR_ID_EDGE_2,
	XBAR_ID_MID_3,
	XBAR_ID_EDGE_3,
	XBAR_ID_NUMBER
};

/*
 * EDMA routing is done in clusters (i.e. dcores) rather than individual EDMAs.
 * for that reason the re-route of EDMA for bining includes (for the most parts)
 * 3 registers configurations in the address decode block:
 * 1. reconfigure the base address of the cluster with the faulty EDMA
 * 2. same for base address of replacing EDMA (EDMA 7)
 * 3. create a new routing for the faulty EDMA using the "spare" LBW_LBW_AUTO
 *    regs.
 * an exception for that is when the faulty is in dcore 3 in which case onle
 * one configuration is needed.
 */
enum edma_binning_addrs {
	EDMA_BIN_ADDR_DEC_FAULTY_CLUSTER,
	EDMA_BIN_ADDR_DEC_REPLACING_CLUSTER,
	EDMA_BIN_ADDR_DEC_FAULTY_REROUTE,
	EDMA_BIN_ADDR_DEC_CONFIG_MAX
};

enum e2e_credit_component {
	E2E_DECODER,
	E2E_CPU,
	E2E_PSOC,
	E2E_PCIE,
	E2E_HBM_DMA,
	E2E_PCIE_DMA,
	E2E_KDMA,
	E2E_HBM_MMU,
	E2E_PCIE_MMU,
	E2E_MME_QMAN,
	E2E_ROT,
	E2E_SM,
	E2E_NIC,
	E2E_ARC_FARM,
	E2E_TPC,
	E2E_MME,
	MSTR_IF_E2E_CRDT_E2E_EMEM_RW_SIZE_ELEMENTS
};

/*
 * enumerates the DRAM configuration status, i.e. whether the DRAM consists
 * of either 4, 5 or 6 functional HBM components
 */
enum dram_config {
	DRAM_CONFIG_4_FUNCTIONAL_HBMS,
	DRAM_CONFIG_5_FUNCTIONAL_HBMS,
	DRAM_CONFIG_6_FUNCTIONAL_HBMS,
	DRAM_CONFIG_FUNCTIONAL_HBMS_SIZE
};

