static void __gaudi2_init_pll_async_if_enable(struct hl_device *hdev)
{
	u32 data;

	/* PSOC enable cfg */
	data = FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_RISE_DELAY_MASK, 0x3);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_FALL_DELAY_MASK, 0x3);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_DETECT_DELAY_MASK,
								0x2);
	WREG32(mmPSOC_GLOBAL_CONF_ASIF_CORE_CFG, data);

	/* All slaves enable cfg */
	data = FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_RISE_DELAY_MASK, 0x5);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_FALL_DELAY_MASK, 0x4);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_CORE_CFG_DETECT_DELAY_MASK,
								0x2);

	WREG32(mmPSOC_CPU_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_PCI_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_XBAR_IF_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_XBAR_IF_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_XBAR_IF_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_XBAR_IF_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_XBAR_MESH_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_XBAR_MESH_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_XBAR_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_XBAR_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_HBM_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmPSOC_MME_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmPMMU_MME_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_TPC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_TPC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_TPC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_TPC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmPSOC_VID_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmPMMU_VID_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_XBAR_BANK_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_XBAR_BANK_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_NIC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_NIC_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_XBAR_MMU_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_XBAR_MMU_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_XBAR_MMU_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_XBAR_MMU_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_XBAR_DMA_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_XBAR_DMA_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_XBAR_DMA_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_XBAR_DMA_PLL_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE0_TS_WRAP_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE1_TS_WRAP_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE2_TS_WRAP_ASIF_SLV_ASIF_CORE_CFG, data);
	WREG32(mmDCORE3_TS_WRAP_ASIF_SLV_ASIF_CORE_CFG, data);
	RREG32(mmDCORE3_TS_WRAP_ASIF_SLV_ASIF_CORE_CFG);
}

static int __gaudi2_async_if_write(struct hl_device *hdev,
			u32 dst_id, u32 addr, u32 value)
{
	u32 data = 0, wr_status = 0;

	/* set data to be written */
	WREG32(mmPSOC_GLOBAL_CONF_ASIF_MSTR_REQ_WR_0, value);

	/* set PUSH register to start write transaction */
	data = FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_MSTR_REQ_PUSH_PWRITE_MASK, 0x1);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_MSTR_REQ_PUSH_DST_ID_MASK,
							dst_id);
	data |= FIELD_PREP(PSOC_GLOBAL_CONF_ASIF_MSTR_REQ_PUSH_LSB_ADDR_MASK,
							addr);

	WREG32(mmPSOC_GLOBAL_CONF_ASIF_MSTR_REQ_PUSH_0, data);

	/* validate write operation succeeded from master side */
	wr_status = RREG32(mmPSOC_GLOBAL_CONF_ASIF_MSTR_REQ_STATUS_0);
	if (wr_status != 0) {
		hl_err(hdev,
		"Failed to write register(0x%x) dst_id(%u)\n", addr, dst_id);
		return -EIO;
	}

	return 0;
}

static int __gaudi2_init_slave_pll_async_if(struct hl_device *hdev,
				enum gaudi2_pll_index pll_index,
				struct gaudi2_pll_params *pll_params)
{
	u32 dst_id, slv_cfg;
	int rc, i;

	dst_id = gaudi2_pll_block_async_if[pll_index].dst_id;
	slv_cfg = gaudi2_pll_block_async_if[pll_index].slv_cfg;

	hl_info(hdev, "pll_index: %u, dst_id: %u\n", pll_index, dst_id);

	/* set operation mode to Early-B response
	 * meaning, master shouldn't read result status after setting slaves
	 * registers, and slave writes responses will be dropped.
	 */

	/* set Early-B mode */
	WREG32_OR(slv_cfg, (1 << 2));

	/* configure slave PLL */
	rc = __gaudi2_async_if_write(hdev, dst_id, PLL_CTRL_CFG_DIV_OFFS,
			pll_params->div_cfg);
	if (rc)
		goto write_error;

	rc = __gaudi2_async_if_write(hdev, dst_id, PLL_CTRL_CFG_OFFS,
			0x101);
	if (rc)
		goto write_error;

	/* set division factor and clock selection */
	for (i = 0 ; i < 4 ; i++) {
		rc = __gaudi2_async_if_write(hdev, dst_id,
				(PLL_CTRL_DIV_FACTOR_0_OFFS + i * 4),
				pll_params->div_fact[i]);
		if (rc)
			goto write_error;

		rc = __gaudi2_async_if_write(hdev, dst_id,
				(PLL_CTRL_DIV_FACTOR_CMD_0_OFFS + i * 4),
				0x1);
		if (rc)
			goto write_error;

		rc = __gaudi2_async_if_write(hdev, dst_id,
				(PLL_CTRL_DIV_EN_0_OFFS + i * 4),
				0x1);
		if (rc)
			goto write_error;

		rc = __gaudi2_async_if_write(hdev, dst_id,
				(PLL_CTRL_DIV_SEL_0_OFFS + i * 4),
				pll_params->div_sel[i]);
		if (rc)
			goto write_error;
	}

	return 0;

write_error:
	hl_err(hdev, "Failed to write register through async if\n");
	return rc;
}

/*
 * HBM scrambler polynom configs for each possible number of functional HBMs
 */
static const u32
scram_hbm_poly_arr[DRAM_CONFIG_FUNCTIONAL_HBMS_SIZE][SCRAM_HBM_POLY_SIZE] = {
	[DRAM_CONFIG_4_FUNCTIONAL_HBMS] = {
		0x0001, 0x0000, 0x0000, 0x0C40, 0x0954, 0x253E,
		0x01E8, 0x25F0, 0x066C, 0x3208, 0x0380, 0x02AA,
		0x160C, 0x2E30, 0x0A8E, 0x0A42
	},
	[DRAM_CONFIG_5_FUNCTIONAL_HBMS] = {
		0x0001, 0xBD78, 0x4CF2, 0x1136, 0x8C92, 0xA818,
		0x51B4, 0x47D6, 0xFB30, 0x495C, 0x38A8, 0x4B7E,
		0x989E, 0x39B0, 0xF3B8, 0x2C4A
	},
	[DRAM_CONFIG_6_FUNCTIONAL_HBMS] = {
		0x0001, 0x1B54, 0x21D6, 0xA242, 0x45A0, 0x6F1A,
		0x4FEA, 0xAAB6, 0x7C42, 0xEE36, 0x12CE, 0x379E,
		0xD508, 0xCCB4, 0x8674, 0xE040
	},
};

static int __gaudi2_init_pll(struct hl_device *hdev,
				enum gaudi2_pll_index pll_index,
				struct gaudi2_pll_params *pll_params)
{
	u32 ctrl_cfg, reg_base;
	int rc, i;

	reg_base = gaudi2_pll_block_bases[pll_index];

	WREG32(reg_base + PLL_CTRL_CFG_DIV_OFFS, pll_params->div_cfg);
	WREG32(reg_base + PLL_CTRL_CFG_OFFS, 0x101);
	ctrl_cfg =  RREG32(reg_base + PLL_CTRL_CFG_OFFS);

	if (!hdev->pldm) {
		/* Wait for PLL lock */
		rc = hl_poll_timeout(
			hdev,
			reg_base + PLL_CTRL_CFG_OFFS,
			ctrl_cfg,
			((ctrl_cfg & 0x00010101) == 0x00010101),
			100,
			GAUDI2_PLL_TIMEOUT_USEC);

		if (rc) {
			hl_err(hdev, "Failed to get PLL %d lock\n",
				pll_index);
			return -EIO;
		}
	}

	for (i = 0 ; i < 4 ; i++) {
		WREG32(reg_base + PLL_CTRL_DIV_FACTOR_0_OFFS + i * 4,
						pll_params->div_fact[i]);
		WREG32(reg_base + PLL_CTRL_DIV_FACTOR_CMD_0_OFFS + i * 4, 0x1);
		WREG32(reg_base + PLL_CTRL_DIV_EN_0_OFFS + i * 4, 0x1);
		WREG32(reg_base + PLL_CTRL_DIV_SEL_0_OFFS + i * 4,
						pll_params->div_sel[i]);
	}

	return 0;
}

static int __gaudi2_init_pll_for_each_instance(struct hl_device *hdev,
			struct gaudi2_pll_params *pll,
			u32 start_pll_idx, u32 last_pll_idx)
{
	int i, rc = 0;

	for (i = start_pll_idx ; i <= last_pll_idx ; i++) {
		if (hdev->pll_async_if_enable)
			rc = __gaudi2_init_slave_pll_async_if(hdev, i, pll);
		else
			rc = __gaudi2_init_pll(hdev, i, pll);

		if (rc)
			return rc;
	}

	return rc;
}

static int __gaudi2_init_mss_pll(struct hl_device *hdev,
					struct gaudi2_device *gaudi2,
					struct gaudi2_pll_params *pll)
{
	/* REFDIV 1 FBDIV 48 POSTDIV1 2 POSTDIV2 1 */
	GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 48, 2, 1);

	/* for nominal freq, divider config are same for all
	 * supported freq i.e 1800/1600/1200
	 */
	GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 0, 1, 2, 5);

	/* Override pll coefficient */
	switch (gaudi2->hbm_pll_freq) {
	case HBM_PLL_1800:
		GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 54, 2, 1);
	default:
		break;
	}

	/* Override divider for half the nominal freq */
	if (unlikely(hdev->half_nominal_pll_mode)) {
		switch (gaudi2->hbm_pll_freq) {
		case HBM_PLL_1600:
			GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 1, 2, 2, 5);
			break;
		case HBM_PLL_1200:
			GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 1, 2, 3, 5);
			break;
		default:
			break;
		}
	}

	return __gaudi2_init_pll_for_each_instance(hdev, pll,
				GAUDI2_MSS_DCORE0_PLL, GAUDI2_MSS_DCORE3_PLL);
}

static int __gaudi2_init_sram_pll(struct hl_device *hdev,
					struct gaudi2_device *gaudi2,
					struct gaudi2_pll_params *pll)
{
	/* REFDIV 1 FBDIV 64 POSTDIV1 4 POSTDIV2 2 */
	GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 64, 4, 2);

	/* for nominal freq, divider config are same for all
	 * supported freq i.e 1800/1600/1200
	 * For SRAM, only div0 is valid, rest are don't care.
	 */
	GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 0, 0, 0, 0);

	return __gaudi2_init_pll_for_each_instance(hdev, pll,
				GAUDI2_SRAM_DCORE2_PLL, GAUDI2_SRAM_DCORE3_PLL);
}

