static int __gauid2_init_dma_pll(struct hl_device *hdev,
					struct gaudi2_device *gaudi2,
					struct gaudi2_pll_params *pll)
{
	/* REFDIV 1 FBDIV 64 POSTDIV1 2 POSTDIV2 1 */
	GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 64, 2, 1);

	/* for nominal freq, divider config are same for all
	 * supported freq i.e 1800/1600/1200
	 */
	GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 0, 1, 2, 5);

	/* Override divider for and coefficient half the nominal freq */
	if (unlikely(hdev->half_nominal_pll_mode)) {
		switch (gaudi2->hbm_pll_freq) {
		case HBM_PLL_1600:
			GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 60, 2, 1);
			GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 1, 2, 2, 5);
			break;
		case HBM_PLL_1200:
			GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 60, 2, 1);
			GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 1, 2, 3, 5);
			break;
		default:
			break;
		}
	}

	return __gaudi2_init_pll_for_each_instance(hdev, pll,
				GAUDI2_DMA_DCORE0_PLL, GAUDI2_DMA_DCORE3_PLL);
}

static int __gauid2_init_hbm_pll(struct hl_device *hdev,
					struct gaudi2_device *gaudi2,
					struct gaudi2_pll_params *pll)
{
	/* divider config are same for all
	 * supported freq i.e 1800/1600/1200
	 */
	GAUDI2_INIT_PLL_DIVIDER_VAL(pll, 0, 1, 3, 5);

	switch (gaudi2->hbm_pll_freq) {
	case HBM_PLL_1800:
		/* 1800Mhz REFDIV 1 FBDIV 36 POSTDIV1 1 POSTDIV2 1 */
		GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 36, 1, 1);
		break;
	case HBM_PLL_1600:
		/* 1600Mhz REFDIV 1 FBDIV 64 POSTDIV1 2 POSTDIV2 1 */
		GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 64, 2, 1);
		break;
	case HBM_PLL_1200:
		/* 1200Mhz REFDIV 1 FBDIV 48 POSTDIV1 2 POSTDIV2 1 */
		GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 48, 2, 1);
		break;
	case HBM_PLL_800:
		/* 800Mhz REFDIV 1 FBDIV 64 POSTDIV1 4 POSTDIV2 1 */
		GAUID2_INIT_PLL_COEFFICIENT(pll, 1, 64, 4, 1);
		break;
	default:
		hl_err(hdev, "Illegal HBM PLL frequency\n");
		return -EINVAL;
	}

	return __gaudi2_init_pll_for_each_instance(hdev, pll,
				GAUDI2_HBM0_PLL, GAUDI2_HBM5_PLL);
}

